Here's a clean implementation using `INotifyPropertyChanged` and `ICommand`:

```csharp
using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows.Input;

public class ProductDetailViewModel : INotifyPropertyChanged
{
    private string _name = string.Empty;
    private decimal _price;
    private bool _isAvailable;
    private bool _isBusy;

    public string Name
    {
        get => _name;
        set => SetProperty(ref _name, value);
    }

    public decimal Price
    {
        get => _price;
        set => SetProperty(ref _price, value);
    }

    public bool IsAvailable
    {
        get => _isAvailable;
        set => SetProperty(ref _isAvailable, value);
    }

    public bool IsBusy
    {
        get => _isBusy;
        set => SetProperty(ref _isBusy, value);
    }

    public ICommand LoadCommand { get; }

    public ProductDetailViewModel()
    {
        LoadCommand = new Command(async () => await LoadProductAsync());
    }

    private async Task LoadProductAsync()
    {
        if (IsBusy) return;

        try
        {
            IsBusy = true;

            // Replace with your actual data service call
            await Task.Delay(500);

            Name = "Sample Product";
            Price = 29.99m;
            IsAvailable = true;
        }
        finally
        {
            IsBusy = false;
        }
    }

    public event PropertyChangedEventHandler? PropertyChanged;

    private bool SetProperty<T>(ref T field, T value,
        [CallerMemberName] string? propertyName = null)
    {
        if (EqualityComparer<T>.Default.Equals(field, value))
            return false;

        field = value;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        return true;
    }
}
```

**Key points:**

- **`SetProperty<T>`** — avoids redundant notifications when the value hasn't changed, and `[CallerMemberName]` auto-fills the property name.
- **`IsBusy` guard** — prevents duplicate loads if the command fires twice.
- **`try/finally`** — ensures `IsBusy` resets even on exceptions.

**XAML binding example:**

```xml
<Label Text="{Binding Name}" />
<Label Text="{Binding Price, StringFormat='{0:C}'}" />
<Switch IsToggled="{Binding IsAvailable, Mode=OneWay}" />
<Button Text="Load" Command="{Binding LoadCommand}" IsEnabled="{Binding IsBusy, Converter={StaticResource InvertBoolConverter}}" />
<ActivityIndicator IsRunning="{Binding IsBusy}" />
```

**Tip:** If you add the [CommunityToolkit.Mvvm](https://learn.microsoft.com/dotnet/communitytoolkit/mvvm/) NuGet package, you can replace all the boilerplate with source generators:

```csharp
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;

public partial class ProductDetailViewModel : ObservableObject
{
    [ObservableProperty] private string _name = string.Empty;
    [ObservableProperty] private decimal _price;
    [ObservableProperty] private bool _isAvailable;

    [RelayCommand]
    private async Task LoadProductAsync()
    {
        Name = "Sample Product";
        Price = 29.99m;
        IsAvailable = true;
    }
}
```

The toolkit auto-generates the public properties, `PropertyChanged` calls, and the `LoadProductCommand` with built-in busy/cancellation support.
